  function base(id,ch,tp,type,q,exp){return{id:id,board:"GEN",klass:"ALL",subject:"COMPAPP",chapter:ch,topic:tp,type:type,diff:"easy",q:q,exp:exp,status:"published"};}
  function addQuestions(ch,tp){
    var p=tp._pairs,s=tp._safe,idBase="COMPAPP-C"+ch+"-"+tp.code.split("-").pop(),terms={en:p.map(function(x){return x.term.en;}),hi:p.map(function(x){return x.term.hi;})};
    var q1=base(idBase+"-Q1",ch,tp.code,"mcq",L("Which term matches: "+p[0].desc.en,"कौन-सा term match करता है: "+p[0].desc.hi),p[0].desc);q1.opts=terms;q1.correct="A";
    var q2=base(idBase+"-Q2",ch,tp.code,"mcq",L("Which term matches: "+p[1].desc.en,"कौन-सा term match करता है: "+p[1].desc.hi),p[1].desc);q2.opts=terms;q2.correct="B";
    var q3=base(idBase+"-Q3",ch,tp.code,"msq",L("Select every safe or effective action.","हर safe या effective action चुनें।"),L("Use the actions that protect accuracy, work and privacy.","Accuracy, work और privacy protect करने वाले actions उपयोग करें।"));q3.opts={en:s.map(function(x){return x.en;}),hi:s.map(function(x){return x.hi;})};q3.correct=["A","B","D"];
    var q4=base(idBase+"-Q4",ch,tp.code,"fill",L("Complete the term: ______ — "+p[2].desc.en,"Term complete करें: ______ — "+p[2].desc.hi),p[2].desc);q4.accepted=[p[2].term.en.toLowerCase(),p[2].term.hi.toLowerCase()];q4.correct=p[2].term.en.toLowerCase();
    var q5=base(idBase+"-Q5",ch,tp.code,"match",L("Match each term to its role.","हर term को उसके role से match करें।"),L("These terms describe the main actions in this lesson.","ये terms lesson के main actions describe करते हैं।"));q5.pairs=p.slice(0,3).map(function(x){return[x.term.en,x.term.hi,x.desc.en,x.desc.hi];});
    [q1,q2,q3,q4,q5].forEach(function(q){if(!data.questions.some(function(x){return x.id===q.id;}))data.questions.push(q);});
  }
  chapters.forEach(function(ch){ch.topics.forEach(function(tp){addQuestions(ch.no,tp);delete tp._pairs;delete tp._safe;});});

